insert into public.academy_adv_subjects (slug, title, summary, description, outcomes, icon, cover_theme, status, sort_order) values
  ('ai-for-contractors', 'AI for Contractors', 'Use AI to estimate, write scopes, answer customers and document jobs faster, with a review step every time.', 'A practical course for owners, estimators and project leads. You''ll learn what today''s AI tools are actually good at, how to write prompts that get usable answers, and how to build AI into estimating, customer communication and jobsite documentation with a review step every time. Each lesson ends with an exercise and a short knowledge check, and the capstone walks one fictional customer inquiry from first message to signed proposal.', array['Know what AI tools are good at and where they fail', 'Write prompts that give usable estimating and scope drafts', 'Answer customers faster without losing your voice', 'Turn jobsite notes and photos into clean daily logs', 'Run one repeatable AI-assisted workflow from inquiry to proposal']::text[], 'Bot', 'navy', 'published', 10),
  ('business-management', 'Contractor Business Management', 'Understand margins, price with confidence, track job costs and cash flow, and grow without losing control.', 'For owners who are good at the work and want the business side to be just as solid. You''ll learn how money really moves through a contracting company, how to price jobs from your own costs instead of gut feel, how to see whether each job made money, how to schedule payments so you aren''t financing customers, how to run several jobs and subcontractors at once, and how to grow without the wheels coming off. Every lesson uses clearly labeled hypothetical numbers you can swap for your own, ends with an exercise and a knowledge check, and connects to the tools in Built2Bid.', array['Read revenue, costs and margin the way a lender does', 'Set prices from overhead and target margin, not guesses', 'Track job costs while the job is running', 'Plan cash flow so payroll and suppliers never surprise you', 'Run crews, subs and several projects at once']::text[], 'BriefcaseBusiness', 'green', 'published', 20),
  ('contractor-automation', 'Contractor Automation', 'Automate follow-ups, reminders and paperwork so fewer jobs fall through the cracks.', null, '{}'::text[], 'Workflow', 'cyan', 'upcoming', 30),
  ('advanced-estimating', 'Advanced Estimating', 'Takeoffs, assemblies, unit costs and contingency for larger and more complex bids.', null, '{}'::text[], 'Calculator', 'amber', 'upcoming', 40),
  ('job-costing', 'Job Costing', 'Estimate-to-actual tracking, cost codes and closing out a job with real numbers.', null, '{}'::text[], 'Landmark', 'slate', 'upcoming', 50),
  ('sales-and-retention', 'Sales and Customer Retention', 'Win more of the right jobs and turn finished projects into repeat work and referrals.', null, '{}'::text[], 'Handshake', 'rose', 'upcoming', 60),
  ('project-scheduling', 'Project Scheduling', 'Sequence trades, plan around lead times and keep several jobs on schedule.', null, '{}'::text[], 'CalendarCheck', 'cyan', 'upcoming', 70),
  ('financial-management', 'Financial Management', 'Budgets, financial statements, taxes to plan for and working with your accountant.', null, '{}'::text[], 'TrendingUp', 'green', 'upcoming', 80),
  ('hiring-and-leadership', 'Hiring and Leadership', 'Hire, train and lead crews and office staff as the business grows.', null, '{}'::text[], 'Users', 'slate', 'upcoming', 90),
  ('business-growth', 'Business Growth', 'Choose where to grow, when to add capacity and how to keep quality as you scale.', null, '{}'::text[], 'Repeat', 'amber', 'upcoming', 100)
